import React, { useEffect, useState } from "react";
import { getCart, removeFromCart, updateQty } from "../api/api";
import { useNavigate } from "react-router-dom";

export default function Cart() {
  const [cart, setCart] = useState({ items: [], total: 0 });
  const navigate = useNavigate();

  const fetchCart = async () => {
    const res = await getCart();
    setCart(res.data);
  };

  useEffect(() => { fetchCart(); }, []);

  const handleRemove = async (id) => {
    await removeFromCart(id);
    fetchCart();
  };

  const handleQtyChange = async (id, qty) => {
    await updateQty(id, qty);
    fetchCart();
  };

  return (
    <div className="container mt-4">
      <h2>Your Cart</h2>
      {cart.items.map((i) => (
        <div key={i.id} className="d-flex justify-content-between align-items-center border p-2 mb-2">
          <div>{i.product.name}</div>
          <div>₹{i.product.price}</div>
          <input type="number" min="1" value={i.qty} onChange={(e) => handleQtyChange(i.id, e.target.value)} />
          <button className="btn btn-danger" onClick={() => handleRemove(i.id)}>Remove</button>
        </div>
      ))}
      <h4>Total: ₹{cart.total.toFixed(2)}</h4>
      {cart.items.length > 0 && <button className="btn btn-primary" onClick={() => navigate("/checkout")}>Proceed to Checkout</button>}
    </div>
  );
}
